import{_ as a,o as n,c as e,ak as p}from"./chunks/framework.Cl9IehmW.js";const g=JSON.parse('{"title":"开始使用Nexus","description":"在快速入门下的子页面（mock）。","frontmatter":{"title":"开始使用Nexus","description":"在快速入门下的子页面（mock）。","order":65536,"path":"guide"},"headers":[],"relativePath":"user-manual/getting-started/guide.md","filePath":"user-manual/getting-started/guide.md"}'),i={name:"user-manual/getting-started/guide.md"};function l(t,s,o,r,c,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>欢迎使用 <strong>PingCode Nexus</strong> 云应用开发平台，本指南将带你从零开始配置 Nexus 环境，并亲手创建一个 <strong>Hello World</strong> 应用。</p><h2 id="🛠️-准备工作" tabindex="-1">🛠️ 准备工作 <a class="header-anchor" href="#🛠️-准备工作" aria-label="Permalink to “🛠️ 准备工作”">​</a></h2><p>在开始之前，你需要做这些准备工作：</p><ul><li><strong>技术栈</strong><ul><li>Nexus 应用基于 TypeScript 编写，因此你需要熟悉 TypeScript，熟悉 Angular 也会对 Nexus 开发有所帮助</li></ul></li><li><strong>Node 环境</strong><ul><li>Node.js 24.x (LTS)</li><li>使用 * * <code>node -v</code> 进行版本验证</li></ul></li><li><strong>注册开发者账号</strong><ul><li>访问 <a href="https://developer.alpha.pingcode.live/signup" target="_blank" rel="noreferrer">PingCode 开发者中心</a> 完成开发者注册</li></ul></li></ul><h2 id="💻-安装与配置-cli" tabindex="-1">💻 安装与配置 CLI <a class="header-anchor" href="#💻-安装与配置-cli" aria-label="Permalink to “💻 安装与配置 CLI”">​</a></h2><p><strong>Nexus CLI</strong> 是你与 PingCode 开发者中心交互的核心工具，支持应用创建、部署和安装。</p><h3 id="全局安装-cli" tabindex="-1">全局安装 CLI <a class="header-anchor" href="#全局安装-cli" aria-label="Permalink to “全局安装 CLI”">​</a></h3><p>打开终端，执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>npm install -g @pc-nexus/cli@latest</span></span></code></pre></div><h3 id="验证安装" tabindex="-1">验证安装 <a class="header-anchor" href="#验证安装" aria-label="Permalink to “验证安装”">​</a></h3><p>确保命令已正确安装到系统路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nexus --version</span></span></code></pre></div><blockquote><p>💡 <strong>提示</strong> ：如果无法识别命令，请检查 npm 环境变量配置。你可以运行 <code>nexus --help</code> 查看所有可用指令。</p></blockquote><h2 id="🔑-身份验证与登录" tabindex="-1">🔑 身份验证与登录 <a class="header-anchor" href="#🔑-身份验证与登录" aria-label="Permalink to “🔑 身份验证与登录”">​</a></h2><p>为了让 CLI 获得操作权限，你需要在开发者中心创建 <strong>个人访问令牌 (Personal Access Token)</strong> 。</p><h3 id="创建-personal-access-token" tabindex="-1">创建 <strong>Personal Access Token</strong> <a class="header-anchor" href="#创建-personal-access-token" aria-label="Permalink to “创建   Personal Access Token”">​</a></h3><ol><li>进入 <a href="https://developer.alpha.pingcode.live/settings/personal-access-tokens" target="_blank" rel="noreferrer">PingCode 开发者中心 - 访问令牌</a></li><li>点击右上角 <strong>[新建]</strong> 按钮</li><li>输入名称（如： <code>nexus-token</code> ），选择过期时间并确定</li><li>立即复制并保存生成的 Token <strong>（关闭弹窗后将无法再次查看）</strong></li></ol><h3 id="执行登录" tabindex="-1">执行登录 <a class="header-anchor" href="#执行登录" aria-label="Permalink to “执行登录”">​</a></h3><p>在终端输入以下命令，并根据提示输入手机号和 Token：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nexus login</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌  Log in to your PingCode Developer account</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>◇  Enter your phone number:</span></span>
<span class="line"><span>│  18800000000</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>◇  Enter your PingCode API token:</span></span>
<span class="line"><span>│  ▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪▪</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>◇  Logged in as 18800000000.</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└  Now try running &#39;nexus create&#39; to start a new app.</span></span></code></pre></div><h2 id="🏗️-创建你的第一个-nexus-应用" tabindex="-1">🏗️ 创建你的第一个 Nexus 应用 <a class="header-anchor" href="#🏗️-创建你的第一个-nexus-应用" aria-label="Permalink to “🏗️ 创建你的第一个 Nexus  应用”">​</a></h2><h3 id="初始化项目" tabindex="-1">初始化项目 <a class="header-anchor" href="#初始化项目" aria-label="Permalink to “初始化项目”">​</a></h3><p>进入你的工作目录，执行 create 命令，选择 <code>pjm-project-page</code> 模板创建应用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nexus create hello-world-app</span></span></code></pre></div><p>切换到应用查看目录结构</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// cd hello-world-app</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hello-world-app</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── handlers/</span></span>
<span class="line"><span>│   │   └── index.ts</span></span>
<span class="line"><span>│   ├── resolvers/</span></span>
<span class="line"><span>│   │   └── index.ts</span></span>
<span class="line"><span>│   └── index.ts</span></span>
<span class="line"><span>├── web/</span></span>
<span class="line"><span>│   └── hello-world/</span></span>
<span class="line"><span>│       ├── src/</span></span>
<span class="line"><span>│       │   ├── app/</span></span>
<span class="line"><span>│       │   │   ├── app.config.ts</span></span>
<span class="line"><span>│       │   │   ├── app.html</span></span>
<span class="line"><span>│       │   │   ├── app.routes.ts</span></span>
<span class="line"><span>│       │   │   ├── app.scss</span></span>
<span class="line"><span>│       │   │   └── app.ts</span></span>
<span class="line"><span>│       │   ├── index.html</span></span>
<span class="line"><span>│       │   ├── main.ts</span></span>
<span class="line"><span>│       │   └── styles.scss</span></span>
<span class="line"><span>│       ├── angular.json</span></span>
<span class="line"><span>│       ├── package.json</span></span>
<span class="line"><span>│       ├── tsconfig.app.json</span></span>
<span class="line"><span>│       ├── tsconfig.json</span></span>
<span class="line"><span>│       └── tsconfig.spec.json</span></span>
<span class="line"><span>├── manifest.yaml</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>└── tsconfig.json</span></span></code></pre></div><ul><li><code>src/</code> 后端/运行时逻辑源码目录</li><li><code>web/</code> 前端资源目录，默认包含一个示例 Web 应用，构建后产物用于作为模块资源被加载</li><li><code>manifest.json</code> Nexus APP 配置文件，定义应用的功能模块、权限及展示位置</li></ul><h2 id="更改应用标题" tabindex="-1">更改应用标题 <a class="header-anchor" href="#更改应用标题" aria-label="Permalink to “更改应用标题”">​</a></h2><p>这个应用使用的 <code>pcm:pjm:project:page</code> 扩展点，这个扩展点用于在 Project 详情页扩展一级菜单页面，让我们将这个页面改为自定义名称。</p><ol><li>在应用的顶层目录打开  <code>manifest.yml</code>  文件</li><li>在 <code>modules</code> 下找到 <code>pcm:pjm:project:page</code> 扩展点配置</li><li>修改扩展点配置中的 <code>title</code> 属性为 <code>New Title</code></li></ol><p>更新后的  <code>manifest.yml</code>  文件应如下所示，其中包含您的标题和应用程序 ID 的值</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>app:</span></span>
<span class="line"><span>  version: 1.0.0</span></span>
<span class="line"><span>  id: e481d841-e3dc-4b4d-907a-7d7954acee57</span></span>
<span class="line"><span>modules:</span></span>
<span class="line"><span>  - key: hello-world-project-page</span></span>
<span class="line"><span>    resource: main</span></span>
<span class="line"><span>    target: pcm:pjm:project:page</span></span>
<span class="line"><span>    resolver:</span></span>
<span class="line"><span>      function: resolver</span></span>
<span class="line"><span>    title: New Title</span></span>
<span class="line"><span>functions:</span></span>
<span class="line"><span>  - key: resolver</span></span>
<span class="line"><span>    handler: index.handler</span></span>
<span class="line"><span>resources:</span></span>
<span class="line"><span>  - key: main</span></span>
<span class="line"><span>    path: web/hello-world/dist</span></span>
<span class="line"><span>permissions:</span></span>
<span class="line"><span>  scopes:</span></span>
<span class="line"><span>    - pcp:app:storage</span></span>
<span class="line"><span>    - pcp:read:app-system-token</span></span>
<span class="line"><span>    - pcp:read:app-user-token</span></span>
<span class="line"><span>    - pcp:read:pcp:pjm:workitem</span></span>
<span class="line"><span>    - pcp:write:pcp:pjm:workitem</span></span></code></pre></div><h2 id="🚀-部署与安装" tabindex="-1">🚀 部署与安装 <a class="header-anchor" href="#🚀-部署与安装" aria-label="Permalink to “🚀 部署与安装”">​</a></h2><p>应用创建后，需要将其上传到云端并分发到你的 PingCode 站点进行安装。</p><h3 id="构建代码" tabindex="-1">构建代码 <a class="header-anchor" href="#构建代码" aria-label="Permalink to “构建代码”">​</a></h3><p>首先需要先构建你的前端代码</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>npm run build-web</span></span></code></pre></div><h3 id="部署代码" tabindex="-1">部署代码 <a class="header-anchor" href="#部署代码" aria-label="Permalink to “部署代码”">​</a></h3><p>执行 <code>deploy</code> 选择 <code>Development</code> 环境，将本地代码编译并上传至 PingCode 云平台。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nexus deploy</span></span></code></pre></div><h3 id="分发应用" tabindex="-1">分发应用 <a class="header-anchor" href="#分发应用" aria-label="Permalink to “分发应用”">​</a></h3><p>执行 <code>distribute</code> ，输入你的 PingCode 站点 Site Url，选择 <code>Development</code> 环境，将应用分发到你的站点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nexus distribute</span></span></code></pre></div><h3 id="安装应用" tabindex="-1">安装应用 <a class="header-anchor" href="#安装应用" aria-label="Permalink to “安装应用”">​</a></h3><p>打开你的 PingCode 站点，进入 [后台管理] --&gt;[应用]-&gt; [应用审核]，在列表选择你的应用点击安装。</p><h3 id="验证效果" tabindex="-1">验证效果 <a class="header-anchor" href="#验证效果" aria-label="Permalink to “验证效果”">​</a></h3><p>安装成功后，打开你的 PingCode 团队站点，找到应用对应的扩展点，即可看到你创建 <strong>Hello World</strong> 页面。</p><h3 id="应用更新" tabindex="-1">应用更新 <a class="header-anchor" href="#应用更新" aria-label="Permalink to “应用更新”">​</a></h3><p>当你修改了 <code>src/</code> 下的代码后，只需再次运行 <code>nexus deploy</code> ，选择 **与上次相同的开发环境 ** 即可同步更改。</p><p><strong>🚀 恭喜你完成了第一个 Nexus 应用的搭建！</strong></p>`,51)])])}const k=a(i,[["render",l]]);export{g as __pageData,k as default};
